import { Category, ContactPointAddress, ContactPointEmail, ContactPointPhone, ErrorEvent, Identity, Order, PartyIdentification } from '../events';
/**
Description: An order is accepted and ready for fulfillment.
*/
export type OrderAccepted = {
    events: Array<ContactPointAddress | ContactPointEmail | ContactPointPhone | Order | Identity | PartyIdentification | ErrorEvent>;
}

export class OrderAcceptedBuilder {

    private orderAccepted: OrderAccepted = {
        events: []
    }

    private contactPointAddress!: ContactPointAddress;
    private contactPointEmail!: ContactPointEmail;
    private contactPointPhone!: ContactPointPhone;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private order!: Order;
    private partyIdentification!: PartyIdentification;

    public withContactPointAddress(contactPointAddress: ContactPointAddress) : OrderAcceptedBuilder {
        this.contactPointAddress = contactPointAddress;
        return this;
    }
    public withContactPointEmail(contactPointEmail: ContactPointEmail) : OrderAcceptedBuilder {
        this.contactPointEmail = contactPointEmail;
        return this;
    }
    public withContactPointPhone(contactPointPhone: ContactPointPhone) : OrderAcceptedBuilder {
        this.contactPointPhone = contactPointPhone;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : OrderAcceptedBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : OrderAcceptedBuilder {
        this.identity = identity;
        return this;
    }
    public withOrder(order: Order) : OrderAcceptedBuilder {
        this.order = order;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : OrderAcceptedBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : OrderAccepted {
        if(this.contactPointAddress) {
            this.orderAccepted.events.push(this.contactPointAddress);
        }
        if(this.contactPointEmail) {
            this.orderAccepted.events.push(this.contactPointEmail);
        }
        if(this.contactPointPhone) {
            this.orderAccepted.events.push(this.contactPointPhone);
        }
        if(this.errorEvent) {
            this.orderAccepted.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.orderAccepted.events.push(this.identity);
        }
        if(this.order) {
            this.orderAccepted.events.push(this.order);
        }
        if(this.partyIdentification) {
            this.orderAccepted.events.push(this.partyIdentification);
        }

        return this.orderAccepted;
    }
}
